WITH cleaned AS (SELECT *, CONCAT_WS('/', status, carrier) AS status_carrier_key, COALESCE(carrier, 'OTHER') AS resolved_carrier FROM shipments WHERE delivered_date > DATE '2023-07-17' AND status = 'LOST') SELECT dim.channel, dim.status AS order_status, src.carrier, COUNT(*) AS rows_total, ROUND(AVG(src.cost), 2) AS avg_cost FROM cleaned src INNER JOIN orders dim ON src.order_id = dim.id GROUP BY dim.channel, dim.status, src.carrier;
